'use strict';

/*
 * Фотогалерея — статичная версия (только HTML + CSS + JS).
 * Сервера нет: пользователи, фото и оценки хранятся в localStorage браузера.
 * Страницы переключаются через адрес после # : #/  #/photo/5  #/add
 */

const PER_PAGE = 10;
const MAX_SIZE = 3 * 1024 * 1024;
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const KEYS = { users: 'pg_users', photos: 'pg_photos_v2', session: 'pg_session' };

/* ================= Хранилище ================= */

function load(key, fallback) {
    try {
        const value = JSON.parse(localStorage.getItem(key));
        return value ?? fallback;
    } catch (e) {
        return fallback;
    }
}

function save(key, value) {
    try {
        localStorage.setItem(key, JSON.stringify(value));
        return true;
    } catch (e) {
        return false; // переполнено хранилище или оно недоступно
    }
}

/* Простой хеш пароля, чтобы не хранить его открытым текстом (для учебного примера) */
function hashPassword(str) {
    let h = 5381;
    for (const ch of 'pg-salt:' + str) h = ((h << 5) + h + ch.charCodeAt(0)) >>> 0;
    return h.toString(16);
}

/* Демо-данные при первом открытии: те же 12 фото, что в макете */
function seed() {
    if (load(KEYS.photos, null)) return;

    const users = getUsers();
    if (!users.some((u) => u.email === 'k@mail.ru')) {
        users.push({ name: 'Константин Константинопольский', email: 'k@mail.ru', phone: '+79101233445', password: hashPassword('qwerty1') });
        save(KEYS.users, users);
    }

    // Порядок как на главной в макете (сверху вниз, слева направо)
    const titles = [
        'July. Summer butterflies.', 'Summer butterflies.', 'Cape Point peninsula South Africa', 'Antelope Canyon',
        'Waves crashing in Brittany, France', 'After the rain', 'Milkyway trail over death valley', 'Nature',
        'July. Summer butterflies.', 'Wheat period.', 'A baby jumping spider on yellow petals', 'July. Summer butterflies.',
    ];
    const date = new Date(new Date().getFullYear(), 7, 15, 12).toISOString(); // «Добавлено 15 августа»

    const photos = titles.map((title, i) => {
        const ratings = {};
        if (i === 0) {
            // Как на детальной странице макета: рейтинг 4.8, 138 оценок
            for (let v = 0; v < 138; v++) ratings[`guest${v}@mail.ru`] = v < 110 ? 5 : 4;
        } else {
            const votes = 3 + ((i * 5) % 9);
            for (let v = 0; v < votes; v++) ratings[`guest${v}@mail.ru`] = 3 + ((i + v) % 3);
        }
        return {
            id: titles.length - i, // сортировка по id по убыванию даёт порядок макета
            description: title,
            src: `mock:${i + 1}`,
            author: 'k@mail.ru',
            createdAt: date,
            ratings,
        };
    });
    save(KEYS.photos, photos);
}

/* Фото из макета встроены в конец файла, загруженные пользователем лежат в localStorage */
function photoSrc(p) {
    return p.src.startsWith('mock:') ? mockImages()[p.src.slice(5)] : p.src;
}

const getUsers = () => load(KEYS.users, []);
const getPhotos = () => load(KEYS.photos, []);
const currentUser = () => {
    const email = load(KEYS.session, null);
    return getUsers().find((u) => u.email === email) || null;
};

/* ================= Утилиты ================= */

const app = document.getElementById('app');

function esc(str) {
    return String(str).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

const ICONS = {
    plus: '<path d="M10 4v12M4 10h12"/>',
    'chevron-down': '<path d="M5 8l5 5 5-5"/>',
    'chevron-left': '<path d="M12 5l-5 5 5 5"/>',
    close: '<path d="M5 5l10 10M15 5L5 15"/>',
    alert: '<circle cx="10" cy="10" r="7"/><path d="M10 6.5v4"/><circle cx="10" cy="13.5" r=".6" fill="currentColor"/>',
    clock: '<circle cx="10" cy="10" r="6.5"/><path d="M10 6.5V10l2.5 1.5"/>',
    trash: '<path d="M4.5 6h11M8 6V4.5h4V6M6 6l.7 9.5h6.6L14 6M8.7 9v4M11.3 9v4"/>',
    check: '<path d="M6 10.5l2.7 2.7L14 7.5"/>',
    spinner: '<path d="M10 3.5a6.5 6.5 0 1 1-6.5 6.5"/>',
    star: '<path fill="currentColor" stroke="none" d="M10 1.8l2.5 5.2 5.6.8-4.1 3.9 1 5.6L10 14.6l-5 2.7 1-5.6-4.1-3.9 5.6-.8z"/>',
};

function icon(name, cls = 'icon') {
    if (name === 'spinner') cls += ' spinner';
    return `<svg class="${cls}" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2" `
        + `stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]}</svg>`;
}

/* Подставляем иконки в статичную разметку index.html */
document.querySelectorAll('[data-icon]').forEach((el) => {
    if (el.tagName === 'SPAN' && !el.className) el.outerHTML = icon(el.dataset.icon);
    else el.innerHTML = icon(el.dataset.icon);
});

const MONTHS = ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа',
    'сентября', 'октября', 'ноября', 'декабря'];

function ruDate(iso) {
    const d = new Date(iso);
    let s = `${d.getDate()} ${MONTHS[d.getMonth()]}`;
    if (d.getFullYear() !== new Date().getFullYear()) s += ` ${d.getFullYear()}`;
    return s;
}

function ratingsLabel(n) {
    const m10 = n % 10, m100 = n % 100;
    let word = 'оценок';
    if (m10 === 1 && m100 !== 11) word = 'оценка';
    else if (m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14)) word = 'оценки';
    return `${n} ${word}`;
}

function ratingStats(photo) {
    const values = Object.values(photo.ratings);
    const avg = values.length ? (values.reduce((a, b) => a + b, 0) / values.length).toFixed(1) : '—';
    return { count: values.length, avg };
}

function shortTitle(text, len = 80) {
    const t = text.trim().replace(/\s+/g, ' ');
    return t.length > len ? t.slice(0, len) + '…' : t;
}

const wait = (ms) => new Promise((r) => setTimeout(r, ms)); // имитация запроса к серверу

function setLoading(button, loading) {
    button.classList.toggle('is-loading', loading);
    button.disabled = loading;
}

function showErrors(form, errors) {
    form.querySelectorAll('[data-error-for]').forEach((el) => {
        const name = el.dataset.errorFor;
        el.textContent = errors[name] || '';
        const field = el.closest('.field');
        if (field) field.classList.toggle('has-error', Boolean(errors[name]));
    });
}

/* Кнопка активна, только когда заполнены все поля (как в макете) */
function bindRequiredState(form) {
    const button = form.querySelector('button[type="submit"]');
    const update = () => {
        const filled = [...form.elements].every((el) => {
            if (!el.name) return true;
            if (el.type === 'checkbox') return el.checked;
            if (el.type === 'file') return el.files.length > 0;
            return el.value.trim() !== '';
        });
        if (!button.classList.contains('is-loading')) button.disabled = !filled;
    };
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    update();
    return update;
}

function showToast(text) {
    const toast = document.createElement('div');
    toast.className = 'toast';
    toast.setAttribute('role', 'status');
    toast.innerHTML = `<span class="toast__check">${icon('check')}</span><p class="toast__text">${esc(text)}</p>`;
    document.body.append(toast);
    setTimeout(() => toast.remove(), 4200);
}

/* ================= Шапка ================= */

function renderNav() {
    const user = currentUser();
    const nav = document.getElementById('nav');
    nav.innerHTML = user
        ? `<span class="nav__user"><span class="nav__hello">Здравствуйте, </span>${esc(user.name)}</span>
           <a href="#" class="nav__link nav__link--muted" id="logout">Выход</a>`
        : `<a href="#" class="nav__link" data-auth="register">Регистрация</a>
           <a href="#" class="nav__link" data-auth="login">Вход</a>`;
    const logout = document.getElementById('logout');
    if (logout) {
        logout.addEventListener('click', (e) => {
            e.preventDefault();
            localStorage.removeItem(KEYS.session);
            renderNav();
            route();
        });
    }
}

/* ================= Главная ================= */

function cardHTML(p) {
    return `
        <a href="#/photo/${p.id}" class="card">
            <img class="card__image" src="${esc(photoSrc(p))}" alt="" loading="lazy" onerror="this.style.visibility='hidden'">
            <span class="card__caption">
                <span class="card__title">${esc(shortTitle(p.description))}</span>
                <span class="card__date">${icon('clock', 'icon card__clock')}<span class="card__date-prefix">Добавлено </span>${ruDate(p.createdAt)}</span>
            </span>
        </a>`;
}

function renderMain() {
    const photos = getPhotos().sort((a, b) => b.id - a.id); // по id по убыванию
    let shown = 0;

    app.innerHTML = `
        <div class="page-head">
            <h1 class="page-title">Фотографии</h1>
            <a href="#/add" class="btn btn--primary btn--add" id="add-btn" aria-label="Добавить фото">${icon('plus')}<span>Добавить фото</span></a>
        </div>
        ${photos.length ? '' : '<p class="empty">Здесь пока нет фотографий. Зарегистрируйтесь и загрузите первую.</p>'}
        <div class="grid" id="photo-grid"></div>
        <button type="button" class="btn btn--outline btn--block btn--more" id="load-more" hidden>
            ${icon('chevron-down', 'icon more-icon')}${icon('spinner')}<span>Показать еще</span>
        </button>`;

    const grid = document.getElementById('photo-grid');
    const more = document.getElementById('load-more');

    const showNext = () => {
        grid.insertAdjacentHTML('beforeend', photos.slice(shown, shown + PER_PAGE).map(cardHTML).join(''));
        shown += PER_PAGE;
        more.hidden = shown >= photos.length;
    };
    showNext();

    // Следующая порция «подгружается» без перезагрузки страницы
    more.addEventListener('click', async () => {
        setLoading(more, true);
        await wait(500);
        showNext();
        setLoading(more, false);
    });

    document.getElementById('add-btn').addEventListener('click', (e) => {
        if (!currentUser()) {
            e.preventDefault();
            openAuth('login');
        }
    });
}

/* ================= Детальная ================= */

function starsHTML(filled) {
    let html = `<div class="stars stars--static" aria-label="Ваша оценка: ${filled} из 5">`;
    for (let i = 1; i <= 5; i++) html += `<span class="star${i <= filled ? ' is-active' : ''}">${icon('star', 'icon star__icon')}</span>`;
    return html + '</div>';
}

function ratePanelHTML(photo, user) {
    if (!user) {
        return `<h2 class="panel__label">Оцените фотографию</h2>
                <p class="panel__muted"><a href="#" data-auth="login" class="panel__link">Войдите</a>, чтобы поставить оценку</p>`;
    }
    if (photo.author === user.email) {
        return `<h2 class="panel__label">Это ваша фотография</h2>
                <p class="panel__muted">Свои фотографии оценивать нельзя</p>`;
    }
    if (photo.ratings[user.email]) {
        return `<h2 class="panel__label">Вы оценили фотографию</h2>${starsHTML(photo.ratings[user.email])}`;
    }
    let stars = '';
    for (let i = 1; i <= 5; i++) {
        stars += `<input type="radio" name="value" value="${i}" id="star-${i}" class="star__input">
                  <label for="star-${i}" class="star" data-value="${i}" title="${i}">${icon('star', 'icon star__icon')}<span class="visually-hidden">${i}</span></label>`;
    }
    return `<form id="rate-form" class="rate-form">
                <h2 class="panel__label">Оцените фотографию</h2>
                <fieldset class="stars"><legend class="visually-hidden">Оценка от 1 до 5</legend>${stars}</fieldset>
                <button type="submit" class="btn btn--primary" disabled>${icon('spinner')}<span>Оценить</span></button>
            </form>`;
}

function renderPhoto(id) {
    const photo = getPhotos().find((p) => p.id === id);
    if (!photo) {
        app.innerHTML = `<div class="page-head"><h1 class="page-title">Фото не найдено</h1></div>
                         <p class="empty"><a href="#/">Вернуться на главную</a></p>`;
        return;
    }
    const user = currentUser();
    const author = getUsers().find((u) => u.email === photo.author);
    const stats = ratingStats(photo);
    document.title = shortTitle(photo.description, 60) + ' — Фотогалерея';

    app.innerHTML = `
        <article class="photo-page">
            <div class="photo-page__image"><img src="${esc(photoSrc(photo))}" alt="${esc(shortTitle(photo.description))}" onerror="this.style.visibility='hidden'"></div>
            <div class="photo-page__info">
                <div class="photo-page__head">
                    <h1 class="photo-page__title">${esc(photo.description)}</h1>
                    <a href="#/" class="btn btn--outline btn--back" aria-label="Назад">${icon('chevron-left')}<span>Назад</span></a>
                </div>
                <p class="photo-page__meta">
                    <span>Добавлено ${ruDate(photo.createdAt)}</span>
                    <span class="photo-page__author">${esc(author ? author.name : 'Неизвестный автор')}</span>
                </p>
                <div class="rating-row">
                    <section class="panel panel--rating" aria-label="Рейтинг">
                        <h2 class="panel__label">Рейтинг</h2>
                        <p class="rating-value" id="rating-avg">${stats.avg}</p>
                        <p class="panel__muted" id="rating-count">${ratingsLabel(stats.count)}</p>
                    </section>
                    <section class="panel panel--rate" id="rate-panel">${ratePanelHTML(photo, user)}</section>
                </div>
            </div>
        </article>`;

    const form = document.getElementById('rate-form');
    if (!form) return;

    const stars = [...form.querySelectorAll('.star')];
    const button = form.querySelector('button');
    const checked = () => Number(form.querySelector('.star__input:checked')?.value || 0);
    const paint = (v) => stars.forEach((s) => s.classList.toggle('is-active', Number(s.dataset.value) <= v));

    stars.forEach((s) => s.addEventListener('mouseenter', () => paint(Number(s.dataset.value))));
    form.querySelector('.stars').addEventListener('mouseleave', () => paint(checked()));
    form.addEventListener('change', () => {
        paint(checked());
        button.disabled = checked() === 0;
    });

    // Оценка без перезагрузки страницы
    form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const value = checked();
        if (!value) return;
        setLoading(button, true);
        await wait(500);

        const photos = getPhotos();
        const target = photos.find((p) => p.id === id);
        target.ratings[user.email] = value; // одна оценка на пользователя
        save(KEYS.photos, photos);

        const s = ratingStats(target);
        document.getElementById('rating-avg').textContent = s.avg;
        document.getElementById('rating-count').textContent = ratingsLabel(s.count);
        document.getElementById('rate-panel').innerHTML = ratePanelHTML(target, user);
    });
}

/* ================= Добавление фото ================= */

/* Уменьшаем фото перед сохранением, чтобы оно поместилось в localStorage */
function fileToDataURL(file, maxSide = 1200) {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => {
            const scale = Math.min(1, maxSide / Math.max(img.width, img.height));
            const canvas = document.createElement('canvas');
            canvas.width = Math.round(img.width * scale);
            canvas.height = Math.round(img.height * scale);
            canvas.getContext('2d').drawImage(img, 0, 0, canvas.width, canvas.height);
            URL.revokeObjectURL(img.src);
            resolve(canvas.toDataURL('image/jpeg', 0.85));
        };
        img.onerror = reject;
        img.src = URL.createObjectURL(file);
    });
}

function renderAdd() {
    const user = currentUser();
    if (!user) {
        location.hash = '#/';
        openAuth('login');
        return;
    }

    app.innerHTML = `
        <h1 class="visually-hidden">Новая фотография</h1>
        <form class="new-photo" id="add-form" novalidate>
            <div class="new-photo__upload">
                <div class="upload" id="dropzone">
                    <input type="file" id="photo-input" name="photo" accept=".jpg,.jpeg,image/jpeg" class="upload__input" aria-label="Фотография">
                    <div class="upload__empty" id="upload-empty">
                        ${icon('plus', 'icon upload__plus')}
                        <p class="upload__title">Загрузите фотографию</p>
                        <p class="upload__hint">(допустимый формат - jpg, максимальный размер - 3 Мб)</p>
                    </div>
                    <img class="upload__preview" id="upload-preview" alt="" hidden>
                    <button type="button" class="upload__remove" id="upload-remove" aria-label="Удалить фото" hidden>${icon('trash')}</button>
                </div>
                <div class="field__error" data-error-for="photo"></div>
            </div>
            <div class="new-photo__body">
                <textarea name="description" id="description" class="title-input" rows="1" maxlength="2000" placeholder="Описание" aria-label="Описание"></textarea>
                <div class="field__error" data-error-for="description"></div>
                <div class="form__error" data-error-for="common"></div>
                <div class="new-photo__actions">
                    <button type="submit" class="btn btn--primary" id="publish" disabled>${icon('spinner')}<span>Опубликовать фотографию</span></button>
                    <p class="form-note form-note--dark">${icon('alert')}<span>Все поля обязательны для заполнения</span></p>
                </div>
            </div>
        </form>`;

    const form = document.getElementById('add-form');
    const dropzone = document.getElementById('dropzone');
    const input = document.getElementById('photo-input');
    const preview = document.getElementById('upload-preview');
    const empty = document.getElementById('upload-empty');
    const removeBtn = document.getElementById('upload-remove');
    const description = document.getElementById('description');
    const publish = document.getElementById('publish');
    const updateButton = bindRequiredState(form);

    const autosize = () => {
        description.style.height = 'auto';
        description.style.height = description.scrollHeight + 'px';
    };
    description.addEventListener('input', autosize);

    const checkFile = (file) => {
        if (!file) return 'Выберите файл';
        if (!/\.jpe?g$/i.test(file.name) || file.type !== 'image/jpeg') return 'Допустим только формат JPG';
        if (file.size > MAX_SIZE) return 'Файл слишком большой, максимум 3 Мб';
        return '';
    };

    const clearFile = () => {
        input.value = '';
        preview.hidden = true;
        preview.removeAttribute('src');
        empty.hidden = false;
        removeBtn.hidden = true;
        dropzone.classList.remove('has-file');
        updateButton();
    };

    const showPreview = () => {
        const file = input.files[0];
        const error = checkFile(file);
        dropzone.classList.toggle('has-error', Boolean(error));
        if (error) {
            clearFile();
            if (file) showErrors(form, { photo: error });
            return;
        }
        showErrors(form, {});
        preview.src = URL.createObjectURL(file);
        preview.hidden = false;
        empty.hidden = true;
        removeBtn.hidden = false;
        dropzone.classList.add('has-file');
        updateButton();
    };

    input.addEventListener('change', showPreview);
    removeBtn.addEventListener('click', clearFile);

    // Загрузка перетаскиванием
    ['dragenter', 'dragover'].forEach((t) => dropzone.addEventListener(t, (e) => {
        e.preventDefault();
        dropzone.classList.add('is-over');
    }));
    ['dragleave', 'drop'].forEach((t) => dropzone.addEventListener(t, (e) => {
        e.preventDefault();
        dropzone.classList.remove('is-over');
    }));
    dropzone.addEventListener('drop', (e) => {
        if (e.dataTransfer.files.length) {
            input.files = e.dataTransfer.files;
            showPreview();
        }
    });

    form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const errors = {};
        const fileError = checkFile(input.files[0]);
        if (fileError) errors.photo = fileError;
        if (!description.value.trim()) errors.description = 'Добавьте описание';
        showErrors(form, errors);
        description.classList.toggle('has-error', Boolean(errors.description));
        dropzone.classList.toggle('has-error', Boolean(errors.photo));
        if (Object.keys(errors).length) return; // при ошибках ничего не сохраняем, текст остаётся в поле

        setLoading(publish, true);
        try {
            const src = await fileToDataURL(input.files[0]);
            const photos = getPhotos();
            const id = photos.reduce((max, p) => Math.max(max, p.id), 0) + 1;
            photos.push({
                id,
                description: description.value.trim(),
                src,
                author: user.email,
                createdAt: new Date().toISOString(),
                ratings: {},
            });
            if (!save(KEYS.photos, photos)) {
                showErrors(form, { common: 'Не хватает места в хранилище браузера. Удалите старые фото или выберите файл поменьше.' });
                setLoading(publish, false);
                return;
            }
            location.hash = `#/photo/${id}`;
            showToast('Ваша фотография опубликована');
        } catch (err) {
            showErrors(form, { common: 'Не удалось прочитать файл' });
            setLoading(publish, false);
        }
    });
}

/* ================= Регистрация и вход ================= */

const authModal = document.getElementById('auth-modal');

function switchTab(name) {
    authModal.querySelectorAll('.tabs__tab').forEach((tab) => {
        const active = tab.dataset.tab === name;
        tab.classList.toggle('is-active', active);
        tab.setAttribute('aria-selected', active);
    });
    authModal.querySelectorAll('[data-panel]').forEach((panel) => {
        panel.hidden = panel.dataset.panel !== name;
    });
}

function openAuth(tab) {
    switchTab(tab);
    authModal.classList.add('is-open');
    authModal.setAttribute('aria-hidden', 'false');
    document.body.classList.add('modal-open');
    const input = authModal.querySelector(`[data-panel="${tab}"] input`);
    if (input) input.focus();
}

function closeAuth() {
    authModal.classList.remove('is-open');
    authModal.setAttribute('aria-hidden', 'true');
    document.body.classList.remove('modal-open');
}

document.addEventListener('click', (e) => {
    const opener = e.target.closest('[data-auth]');
    if (opener) {
        e.preventDefault();
        openAuth(opener.dataset.auth);
        return;
    }
    const tab = e.target.closest('.tabs__tab');
    if (tab) {
        switchTab(tab.dataset.tab);
        return;
    }
    if (e.target.closest('[data-close-modal]')) closeAuth();
});

document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') closeAuth();
});

function validateRegistration(form) {
    const v = (name) => form.elements[name].value.trim();
    const errors = {};

    const name = v('name');
    if (!name) errors.name = 'Введите имя';
    else if (!/^[А-Яа-яЁё\s-]+$/.test(name)) errors.name = 'Только русские буквы, пробелы и дефисы';

    const email = v('email');
    if (!email) errors.email = 'Введите email';
    else if (!EMAIL_RE.test(email)) errors.email = 'Некорректный email';
    else if (getUsers().some((u) => u.email.toLowerCase() === email.toLowerCase())) {
        errors.email = 'Пользователь с таким email уже зарегистрирован';
    }

    const phone = v('phone').replace(/[\s\-()]/g, '');
    if (!phone) errors.phone = 'Введите телефон';
    else if (!/^(\+7|8)9\d{9}$/.test(phone)) errors.phone = 'Нужен мобильный номер, например 8 910 123 34 45';

    const pass = form.elements.password.value;
    if (!pass) errors.password = 'Введите пароль';
    else if (pass.length < 6) errors.password = 'Минимум 6 символов';
    else if (/^\d+$/.test(pass)) errors.password = 'Пароль не может состоять только из цифр';

    const pass2 = form.elements.password_repeat.value;
    if (!pass2) errors.password_repeat = 'Повторите пароль';
    else if (pass !== pass2) errors.password_repeat = 'Пароли не совпадают';

    if (!form.elements.agree.checked) errors.agree = 'Нужно согласие на обработку персональных данных';
    return errors;
}

function afterLogin(email) {
    save(KEYS.session, email);
    closeAuth();
    renderNav();
    if (location.hash === '#/' || location.hash === '') route();
    else location.hash = '#/'; // после входа — на главную
}

const registerForm = document.getElementById('register-form');
bindRequiredState(registerForm);
registerForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    const errors = validateRegistration(registerForm);
    showErrors(registerForm, errors);
    if (Object.keys(errors).length) return;

    const button = registerForm.querySelector('button[type="submit"]');
    setLoading(button, true);
    await wait(500);
    const f = registerForm.elements;
    const email = f.email.value.trim();
    const users = getUsers();
    users.push({
        name: f.name.value.trim(),
        email,
        phone: '+7' + f.phone.value.replace(/[\s\-()]/g, '').slice(-10),
        password: hashPassword(f.password.value),
    });
    save(KEYS.users, users);
    setLoading(button, false);
    registerForm.reset();
    button.disabled = true;
    afterLogin(email);
});

const loginForm = document.getElementById('login-form');
bindRequiredState(loginForm);
loginForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    const email = loginForm.elements.email.value.trim();
    const password = loginForm.elements.password.value;
    const errors = {};
    if (!email) errors.email = 'Введите email';
    else if (!EMAIL_RE.test(email)) errors.email = 'Некорректный email';
    if (!password) errors.password = 'Введите пароль';
    showErrors(loginForm, errors);
    if (Object.keys(errors).length) return;

    const button = loginForm.querySelector('button[type="submit"]');
    setLoading(button, true);
    await wait(400);
    const user = getUsers().find((u) => u.email.toLowerCase() === email.toLowerCase());
    setLoading(button, false);
    if (!user || user.password !== hashPassword(password)) {
        showErrors(loginForm, { common: 'Неверный email или пароль' });
        return;
    }
    loginForm.reset();
    button.disabled = true;
    afterLogin(user.email);
});

/* ================= Маршрутизация ================= */

function route() {
    document.title = 'Фотогалерея';
    const hash = location.hash || '#/';
    const photoMatch = hash.match(/^#\/photo\/(\d+)$/);
    if (photoMatch) renderPhoto(Number(photoMatch[1]));
    else if (hash === '#/add') renderAdd();
    else renderMain();
    window.scrollTo(0, 0);
}

window.addEventListener('hashchange', route);

seed();
renderNav();
route();

